let result = ${ echo Hello${x}! }
std.println(result)

function fibonacci(n)
  if n <= 1 then
    return n
  else
    return fibonacci(n - 1) + fibonacci(n - 2)
  end
end

let result = fibonacci(8)
std.println(result)

